.indicator-header {
  padding-left: 0;
}
[data-sort] {
  position: relative;
  padding-right: 18px;
  cursor: pointer;
}
[data-order=desc]::after {
  position: absolute;
  top: 12px;
  right: 4px;
  display: block;
  content: "";
  border-top: 5px solid var(--text-color-lightest);
  border-right: 5px solid transparent;
  border-left: 5px solid transparent;
}
