/* src/fava/styles/fava/layout.css */
:root {
  --aside-width: 160px;
}
body {
  display: grid;
  grid: "header header" auto "aside main" 1fr / var(--aside-width) 1fr;
  width: 100vw;
  height: 100vh;
  padding: 0;
}
header {
  display: flex;
  flex-wrap: wrap;
  grid-area: header;
  gap: 0.5em;
  align-items: center;
  padding: 0.5em;
  color: var(--header-color);
  background-color: var(--header-background);
}
article {
  position: relative;
  grid-area: main;
  padding: 1.5em;
  overflow-x: auto;
}
article:has(> .fixed-fullsize-container) {
  padding: 0;
}
.fixed-fullsize-container {
  width: 100%;
  max-width: 100vw;
  height: 100%;
  max-height: 100vh;
}
@media (width <= 767px) {
  article {
    padding: 1em;
  }
  body {
    display: block;
    font-size: 16px;
    transition: var(--transitions);
  }
  body:has(> article > .fixed-fullsize-container) {
    display: grid;
    grid-template: "header" max-content "main" 1fr;
  }
  header {
    padding-left: 50px;
  }
}
@media print {
  body {
    grid-template: "header" max-content "main" 1fr;
  }
}

/* src/fava/styles/fava/components.css */
svelte-component.error {
  display: block;
  padding: 0.5em;
  margin: 0.5em;
  color: var(--error);
  border: 1px solid var(--error);
}
details {
  display: block;
  min-width: 400px;
  margin-bottom: 0.5em;
  border: 1px solid var(--table-border);
}
details.inactive {
  opacity: 0.5;
}
details summary {
  position: relative;
  display: flex;
  gap: 0.5em;
  align-items: center;
  padding: 0.25em 0.5em 0.25em 30px;
  cursor: pointer;
  background-color: var(--summary-background);
}
details summary::before {
  position: absolute;
  top: 50%;
  left: 10px;
  margin-right: 0.5em;
  content: "";
  border-top: 9px solid var(--treetable-expander);
  border-right: 6px solid transparent;
  border-left: 6px solid transparent;
  transform: translateY(-50%) rotate(270deg);
}
details summary::-webkit-details-marker {
  display: none;
}
details.error summary {
  background-color: var(--error);
}
details[open] summary::before {
  transform: translateY(-50%) rotate(0deg);
}
details summary pre {
  display: inline-block;
  padding: 3px 6px;
  margin: 0;
}
details > div {
  padding: 0.5em;
}

