/* src/fava/styles/fava/fonts.css */

/* src/fava/styles/fava/grid.css */
:root {
  --flex-gap: 0.5rem;
}
.flex-column {
  display: flex;
  flex-direction: column;
  gap: var(--flex-gap);
  > h3 {
    margin: 0;
  }
}
.flex-row {
  display: flex;
  flex-wrap: wrap;
  gap: var(--flex-gap);
  align-items: center;
  > h3 {
    margin: 0;
  }
  > label {
    display: contents;
  }
  @media (hover: hover) and (width > 767px) {
    .remove-row {
      opacity: 0;
    }
  }
  &:hover .remove-row {
    opacity: 1;
  }
}

/* src/fava/styles/fava/journal-table.css */
.flex-table {
  p,
  li,
  ul,
  ol {
    padding: 0;
    margin: 0;
  }
  p {
    display: flex;
    > * {
      flex-shrink: 0;
      padding: 2px 4px;
    }
  }
  .num {
    font-family: var(--font-family-monospaced);
    text-align: right;
  }
  .head p > * {
    padding: 3px 4px;
    font-family: inherit;
    color: var(--table-header-text);
    background-color: var(--table-header-background);
  }
}
.journal {
  display: flex;
  flex-direction: column;
  p,
  dl {
    border-bottom: thin solid var(--table-border);
  }
  > li,
  &.show-custom .custom.budget,
  &.show-document .document.discovered,
  &.show-document .document.linked,
  .metadata,
  .postings {
    display: none;
  }
  & .head,
  &.show-balance .balance,
  &.show-close .close,
  &.show-custom .custom,
  &.show-document .document,
  &.show-note .note,
  &.show-open .open,
  &.show-pad .pad,
  &.show-query .query {
    display: block;
  }
  &.show-postings .postings,
  &.show-metadata .metadata {
    display: block;
  }
  li.show-full-entry .postings,
  li.show-full-entry .metadata {
    display: block;
  }
  &.show-transaction.show-cleared .transaction.cleared,
  &.show-transaction.show-pending .transaction.pending,
  &.show-transaction.show-other .transaction.other,
  &.show-document.show-discovered .document.discovered,
  &.show-document.show-linked .document.linked,
  &.show-custom.show-budget .custom.budget {
    display: block;
  }
  .payee {
    cursor: pointer;
  }
  .postings {
    font-size: 0.9em;
    background-color: var(--journal-postings);
    opacity: 0.8;
    .num {
      overflow: auto;
      line-height: 1rem;
    }
  }
  .transaction:hover {
    background: var(--journal-hover-highlight);
  }
  .metadata {
    font-size: 0.9em;
    dt {
      float: left;
      width: auto;
      min-width: 4rem;
      padding: 2px 3px;
      margin-left: 9rem;
      color: var(--journal-metadata);
      cursor: pointer;
    }
    dd {
      padding: 2px 3px;
      margin-left: 15rem;
      cursor: pointer;
    }
  }
  p > .num {
    width: min(calc(15%), 20rem);
    border-left: 1px solid var(--table-border);
  }
  .datecell,
  .flag {
    text-align: center;
    background-color: var(--entry-background);
  }
  .datecell {
    width: 6rem;
    white-space: nowrap;
  }
  .flag {
    width: 3rem;
  }
  .change {
    font-weight: 500;
  }
  .description {
    flex: 1;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    .separator::before {
      padding: 2px;
      margin: 0 6px;
      font-weight: bold;
      color: var(--text-color-lighter);
      content: "\2022";
    }
    .num {
      margin: 0 5px;
    }
  }
  .show-postings .description {
    white-space: normal;
  }
  .tag,
  .link {
    margin-left: 8px;
    font-size: 0.9em;
    cursor: pointer;
  }
  .tag {
    color: var(--journal-tag);
  }
  .link {
    color: var(--journal-link);
  }
  .bal {
    background-color: var(--entry-background);
  }
  a:hover {
    filter: brightness(80%);
  }
  .filename,
  .url {
    font-family: var(--font-family-monospaced);
    font-size: 0.9em;
  }
  .document .filename {
    margin-left: 1em;
  }
  .indicators {
    display: flex;
    flex-shrink: 3;
    flex-wrap: wrap;
    align-items: center;
    justify-content: flex-end;
    cursor: pointer;
    span {
      min-width: 6px;
      height: 6px;
      padding: 0;
      margin-right: 4px;
      background-color: var(--journal-posting-indicator);
      border-radius: 3px;
    }
    .pending,
    .other {
      background-color: var(--entry-background);
    }
    .metadata-indicator {
      height: 16px;
      padding: 0 6px;
      font-size: 10px;
      line-height: 16px;
      color: var(--journal-metadata-indicator);
      text-transform: lowercase;
      border-radius: 20px;
    }
  }
}
@media (width <= 767px) {
  .journal {
    p {
      flex-wrap: wrap;
    }
    > li {
      border-top: thin solid var(--entry-background);
    }
    .head .flag {
      flex-grow: 1;
      text-align: left;
    }
    .description {
      flex: inherit;
      order: 1;
      width: 100%;
    }
    .indicators {
      flex-grow: 1;
    }
    .balance .num {
      width: 35%;
    }
    .balance .change.num {
      display: none;
    }
    .postings .datecell,
    .postings .flag {
      display: none;
    }
    .postings .description {
      flex-grow: 1;
      order: inherit;
      width: inherit;
    }
    .metadata dt,
    .metadata dd {
      margin-left: initial;
    }
  }
}

/* src/fava/styles/fava/tree-table.css */
.tree-table-new p {
  margin-top: -1px;
}
.tree-table-new p > span {
  margin-right: -1px;
  border: 1px solid var(--table-border);
}
.tree-table-new .num {
  width: 9em;
}
.tree-table-new .other {
  width: 12em;
}
.tree-table.fullwidth {
  display: block;
  max-width: 100%;
  overflow-x: auto;
}
.tree-table p {
  margin-top: -1px;
}
.tree-table p > span {
  margin-right: -1px;
  border: 1px solid var(--table-border);
}
.tree-table .account-cell {
  display: flex;
  flex: 1;
  align-items: center;
  min-width: 14em;
  max-width: 30em;
}
.tree-table .account-cell.depth-1 {
  min-width: 13em;
  max-width: 29em;
  margin-left: 1em;
}
.tree-table .account-cell.depth-2 {
  min-width: 12em;
  max-width: 28em;
  margin-left: 2em;
}
.tree-table .account-cell.depth-3 {
  min-width: 11em;
  max-width: 27em;
  margin-left: 3em;
}
.tree-table .account-cell.depth-4 {
  min-width: 10em;
  max-width: 26em;
  margin-left: 4em;
}
.tree-table .account-cell.depth-5 {
  min-width: 9em;
  max-width: 25em;
  margin-left: 5em;
}
.tree-table .account-cell.depth-6 {
  min-width: 8em;
  max-width: 24em;
  margin-left: 6em;
}
.tree-table .account-cell.depth-7 {
  min-width: 7em;
  max-width: 23em;
  margin-left: 7em;
}
.tree-table .account-cell.depth-8 {
  min-width: 6em;
  max-width: 22em;
  margin-left: 8em;
}
.tree-table .account-cell.depth-9 {
  min-width: 5em;
  max-width: 21em;
  margin-left: 9em;
}
.tree-table .account-cell a {
  margin-left: 1em;
}
.tree-table .has-children {
  cursor: pointer;
}
.tree-table .has-children::before {
  margin: 0 -10px 0 0;
  content: "";
  border-top: 5px solid var(--treetable-expander);
  border-right: 5px solid transparent;
  border-left: 5px solid transparent;
}
.tree-table .num {
  width: 10em;
}
.tree-table .num a {
  display: block;
  color: inherit;
}
.tree-table .other {
  width: 13em;
}
.tree-table .other a {
  display: block;
  color: inherit;
}
.tree-table .balance-children {
  display: block;
  opacity: 0.7;
}
.tree-table .has-balance .balance {
  display: block;
}
.tree-table .has-balance .balance-children {
  display: none;
}
.tree-table .toggled ol {
  display: none;
}
.tree-table .toggled .balance {
  display: none;
}
.tree-table .toggled .balance-children {
  display: block;
  color: var(--text-color);
}
.tree-table .toggled .has-children::before {
  transform: rotate(270deg);
}
.tree-table .expand-all {
  margin-left: 15px;
  font-weight: normal;
  color: inherit;
  opacity: 0.5;
}
.tree-table .diff {
  margin-right: 3px;
  font-size: 0.9em;
  white-space: nowrap;
}
.tree-table .diff.negative {
  color: var(--diff-negative);
}
.tree-table .diff.positive {
  color: var(--diff-positive);
}
.two-currencies {
  font-size: 0.9em;
}
.two-currencies .num {
  width: 8em;
}
.two-currencies .other {
  width: 11em;
}

/* src/fava/styles/fava/charts.css */
svg text {
  font-family: var(--font-family);
  fill: var(--text-color-lightest);
}
.tooltip {
  position: absolute;
  z-index: var(--z-index-floating-ui);
  min-width: 5em;
  padding: 0.5em;
  font-family: var(--font-family-monospaced);
  text-align: center;
  pointer-events: none;
  background: var(--background);
  border: 1px solid var(--border);
  box-shadow: var(--box-shadow-button);
  opacity: 0;
  transform: translate(-50%, -100%);
}
.tooltip::before {
  position: absolute;
  top: 100%;
  left: 50%;
  width: 0;
  height: 0;
  margin-left: -15px;
  content: "";
  border: 15px solid transparent;
  border-top-color: var(--border);
}
.tooltip em {
  display: block;
  margin-top: 5px;
  font-family: var(--font-family);
  color: var(--text-color-lightest);
}

/* src/fava/styles/fava/editor.css */
.cm-editor .cm-gutters {
  background: var(--sidebar-background);
  border-right: 1px solid var(--sidebar-border);
}
.cm-editor .cm-scroller {
  font-family: var(--font-family-editor);
}
.cm-editor .cm-placeholder {
  color: var(--placeholder-color);
}
.cm-editor .cm-tooltip {
  background-color: var(--sidebar-border);
}
.cm-editor .cm-activeLine {
  background-color: var(--editor-activeline);
}
.cm-editor .cm-selectionBackground {
  background-color: var(--editor-activeline);
}
.cm-editor.cm-focused > .cm-scroller > .cm-selectionLayer .cm-selectionBackground {
  background-color: var(--editor-activeline);
}
.cm-editor .cm-selectionMatch {
  background-color: var(--editor-selectionmatch);
}
.cm-editor .cm-cursor {
  border-left-color: var(--text-color-lighter);
}

/* src/fava/styles/fava/help.css */
.help {
  --help-max-width: 600px;
  max-width: calc(var(--help-max-width) + 160px);
}
.help-text {
  max-width: var(--help-max-width);
  font-size: 16px;
}
.help-text .cm-editor {
  font-size: 14px;
}
.help-text h1 {
  margin: 0 0 1rem;
  font-weight: 500;
}
.help-text > div {
  margin-bottom: 1em;
}
.help-text code {
  font-size: 0.9em;
}
.help-text ul {
  padding-left: 2em;
}
.help-text li {
  list-style-type: disc;
}
.help-sidebar {
  float: right;
  padding: 10px 10px 0;
  margin: 0 0 10px 10px;
  font-size: 1.1em;
  background-color: var(--help-sidebar-background);
  border: 1px solid var(--help-sidebar-border);
}
.help-sidebar a:hover,
.help-sidebar a.selected {
  font-weight: 500;
}

/* src/fava/styles/fava/notifications.css */
.notifications {
  position: fixed;
  top: 60px;
  right: 10px;
  width: 400px;
}
.notifications li {
  display: block;
  width: 100%;
  padding: 5px 10px;
  margin-bottom: 0.5em;
  color: var(--notification-color);
  white-space: pre-wrap;
  cursor: pointer;
  background-color: var(--green);
}
.notifications .error {
  background-color: var(--error);
}
.notifications .warning {
  color: var(--dark-gray);
  background-color: var(--yellow);
}

/* src/fava/styles/orangecount.css */
#main-content a.button:link,
#main-content a.button:visited {
  color: var(--button-color);
}
